INSERT INTO t_p61016064_digital_innovation_i.glossary_terms
(term, aliases, short_definition, plain_explanation, why_matters, example, category, scope, source, is_verified) VALUES

('Блок внутреннего контроля', 'БВК, Блок ВК', 'Объединение подразделений банка, отвечающих за контроль, комплаенс, финмониторинг и аудит.', 'Включает четыре подразделения: Службу внутреннего аудита, Департамент по взаимодействию с контрольно-надзорными органами и противодействия недобросовестным практикам, Департамент финансового мониторинга и Департамент внутреннего контроля и комплаенса. Вместе они закрывают вторую и третью линии защиты банка.', 'Это периметр вашей ответственности за цифровизацию. Каждое из четырёх подразделений имеет свои процессы, регуляторные требования и потенциал автоматизации.', 'Инициатива по единой платформе управления контрольными процедурами затрагивает сразу три департамента Блока.', 'org', 'global', 'seed', TRUE),

('Служба внутреннего аудита', 'СВА, внутренний аудит', 'Подразделение третьей линии защиты, независимо оценивающее эффективность контроля и управления рисками.', 'Проверяет, работают ли первая и вторая линии: выполняются ли контрольные процедуры, адекватны ли они рискам, соблюдаются ли регламенты. Подчиняется, как правило, Совету директоров, чтобы сохранять независимость от менеджмента.', 'Из-за требования независимости автоматизация СВА имеет особенности: доступ к данным должен быть широким, но система не должна зависеть от проверяемых подразделений.', 'Аудиторская проверка процессов финансового мониторинга с формированием отчёта о недостатках.', 'org', 'global', 'seed', TRUE),

('Департамент финансового мониторинга', 'ДФМ', 'Подразделение, отвечающее за ПОД/ФТ: выявление подозрительных операций и взаимодействие с Росфинмониторингом.', 'Реализует требования 115-ФЗ: идентификация клиентов, мониторинг операций, выявление подозрительных схем, направление сведений в уполномоченный орган. Один из самых нагруженных объёмом данных участков банка.', 'Самый очевидный кандидат на применение ИИ: огромные объёмы однотипных проверок, высокая доля ручного анализа, чёткие критерии. Именно здесь уже накоплена ваша фактура по функциям.', 'Анализ операций клиента на соответствие критериям необычных сделок с формированием сообщения в Росфинмониторинг.', 'org', 'global', 'seed', TRUE),

('Департамент внутреннего контроля и комплаенса', 'ДВКиК, комплаенс-департамент', 'Подразделение второй линии защиты, отвечающее за систему внутреннего контроля и соответствие требованиям.', 'Разрабатывает контрольные процедуры, ведёт матрицы рисков и контролей, контролирует конфликт интересов, следит за соблюдением внутренних политик и регуляторных требований. Задаёт правила, по которым работает первая линия.', 'Здесь основной потенциал — оркестрация процессов и цифровые матрицы рисков и контролей вместо разрозненных таблиц.', 'Ведение реестра контрольных процедур и контроль их фактического исполнения подразделениями.', 'org', 'global', 'seed', TRUE),

('Департамент по взаимодействию с контрольно-надзорными органами и противодействия недобросовестным практикам', 'ДВКНО, взаимодействие с регуляторами', 'Подразделение, отвечающее за коммуникацию с надзорными органами и борьбу с недобросовестными практиками.', 'Ведёт переписку и взаимодействие с ЦБ и другими надзорными органами, готовит ответы на запросы и предписания, а также выявляет и пресекает недобросовестные практики — мисселинг, навязывание услуг, некорректные продажи.', 'Здесь высокий потенциал автоматизации работы с запросами регулятора: сроки жёсткие, объём документов большой, а подготовка ответов сегодня во многом ручная.', 'Подготовка ответа на предписание регулятора со сбором данных из нескольких подразделений в установленный срок.', 'org', 'global', 'seed', TRUE),

('Мисселинг', 'Misselling, недобросовестная продажа', 'Продажа клиенту продукта, не соответствующего его потребностям, с искажением или умолчанием существенных условий.', 'Клиенту продают инвестиционный продукт под видом вклада, не раскрывают риски или навязывают ненужную страховку. Формально согласие получено, по сути клиент введён в заблуждение.', 'Это профильная тема одного из департаментов Блока. Выявление мисселинга хорошо поддаётся автоматизации — через анализ записей разговоров, жалоб и параметров сделок.', 'Клиенту вместо вклада оформили полис инвестиционного страхования жизни, не объяснив отсутствие гарантии доходности.', 'internal_control', 'global', 'seed', TRUE),

('Предписание регулятора', 'Предписание ЦБ, надзорное предписание', 'Обязательное для исполнения требование надзорного органа устранить выявленное нарушение.', 'Регулятор фиксирует нарушение и устанавливает срок на устранение. Неисполнение влечёт санкции — от штрафа до ограничения операций. Требует скоординированного ответа нескольких подразделений в жёсткий срок.', 'Автоматизация работы с предписаниями — это контроль сроков, сбор доказательств устранения и единый след. Сильный кандидат на цифровизацию с измеримым эффектом.', 'Предписание об устранении недостатков в процедурах идентификации клиентов в 30-дневный срок.', 'internal_control', 'global', 'seed', TRUE);
